"""Differential driver: candidate entry vs the naive reference model."""
import json, os, subprocess, sys, pathlib
sys.path.insert(0, '/workspace/dev')
import ref

CAND = '/workspace/submission/main.py'
ENV = dict(os.environ, PYTHONDONTWRITEBYTECODE='1')

def candidate_out(data):
    p = subprocess.run([sys.executable, '-B', CAND], input=data.encode(), stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, env=ENV)
    if p.returncode != 0:
        raise RuntimeError('candidate exit %d: %s' % (p.returncode, p.stderr[:400]))
    return p.stdout.decode()

def deep_same(a, b, path=''):
    if type(a) is not type(b):
        # allow int/float normalisation only for ints
        if isinstance(a, int) and isinstance(b, int):
            pass
        else:
            return '%s: type %s vs %s' % (path, type(a), type(b))
    if isinstance(a, dict):
        if set(a) != set(b):
            return '%s: keyset' % path
        for k in a:
            r = deep_same(a[k], b[k], path + '/' + str(k))
            if r: return r
        return None
    if isinstance(a, list):
        if len(a) != len(b):
            return '%s: len %d vs %d' % (path, len(a), len(b))
        for i, (x, y) in enumerate(zip(a, b)):
            r = deep_same(x, y, '%s[%d]' % (path, i))
            if r: return r
        return None
    if a != b:
        return '%s: %r vs %r' % (path, a, b)
    return None

