    elif force_bad == 'work' and d >= 1:
        idx = max(range(d), key=lambda i: tasks[i][2])
        groups[tasks[idx][1]] = [1, 1]
        tasks[idx][2] = 10 ** 9
    elif force_bad == 'capacity' and d >= 1:
        gid = tasks[0][1]
        if fp[gid]:
            caps[min(fp[gid])] = 0
        else:
            return None
    elif force_bad == 'range':
        if d == 0:
            return None
        tasks[0][0] = tcount
    elif force_bad == 'emptyquotaok' and d >= 1:
        pass

    def qmake():
        return {'groups': [rng.randrange(g) for _ in range(rng.randint(0, 5))],
                'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 6))],
                'tasks': [rng.randrange(d) for _ in range(rng.randint(0, 5))] if d else []}

    txs = []
    for _ in range(ntx if ntx is not None else rng.randint(0, 12)):
        stale = rng.random() < 0.1
        r = rng.choice([0, 1, 2, 10 ** 9]) if stale else None
        # revision tracking is approximate; the reference/candidate decides
        edits = []
        count = edit_count if edit_count is not None else rng.randint(0, 8)
        chaotic = rng.random() < wild
        for _ in range(count):
            kinds = ['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap']
            weights = [10, 10, 6, 6, 6, 8, 6, 8] if chaotic else [12, 8, 2, 4, 6, 6, 4, 6]
            kind = rng.choices(kinds, weights=weights)[0]
            if kind in ('move', 'weight', 'class', 'bind', 'pin'):
                if d == 0:
                    kind = 'quota' if g else 'cap'
                else:
                    tid = rng.randrange(d)
                    if kind == 'move':
                        pool = same_key[tid and tasks[tid][1]] if not chaotic else list(range(g))
                        if chaotic and rng.random() < .5:
                            pool = list(range(g))
                        edits.append(['move', tid, rng.choice(pool)])
                    elif kind == 'weight':
                        hi = 10 ** 9 if chaotic else 6
                        edits.append(['weight', tid, rng.randint(1, hi)])
                    elif kind == 'class':
                        edits.append(['class', tid, rng.choice([0, 1, 7, 42, 10 ** 9] if chaotic else [gkey[tasks[tid][1]][1]])])
                    elif kind == 'bind':
                        if chaotic:
                            edits.append(['bind', tid, rng.randrange(tcount)])
                        else:
                            edits.append(['bind', tid, rng.choice(by_dom[gkey[tasks[tid][1]][0]])])
                    elif kind == 'pin':
                        edits.append(['pin', tid, rng.randint(0, 1)])
                    continue
            if kind == 'quota':
                if g == 0:
                    continue
                edits.append(['quota', rng.randrange(g), rng.randint(0, 64) if chaotic else rng.randint(1, 20)])
            elif kind == 'budget':
                if g == 0:
                    continue
                edits.append(['budget', rng.randrange(g), rng.choice([1, 10 ** 12]) if chaotic else rng.choice([10, 10 ** 12])])
            elif kind == 'cap':
                edits.append(['cap', rng.randrange(n), rng.randint(0, 10 ** 9) if chaotic else rng.randint(4, 60)])
        txs.append({'revision': r, 'edits': edits, 'query': qmake()})
    if r is None:
        pass
    # first pass revision values default: set sequentially below in driver
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': qmake(), 'transactions': txs, '_loads': loads}

def sequential_revisions(rng, session, share=0.85):
    """Rewrite transaction revisions so most of them match the running counter."""
    rev = 0
    for tx in session['transactions']:
        if tx['revision'] is None:
            tx['revision'] = rev
        # transactions may be accepted or rejected; keep mostly the live counter
    # simulate accept/reject quickly is impossible here; leave as-is
    return session

def build_request(seed, sessions=2, force_bad=None, **kw):
    rng = random.Random(seed)
    out = []
    for _ in range(sessions):
        spec = rng.choice(TOPOS)
        s = build_session(rng, spec, force_bad=force_bad, **kw)
        if s is None:
            continue
        s.pop('_loads', None)
        # transaction revisions: chain them so that accepted ones advance
        rev = 0
        for tx in s['transactions']:
            if tx['revision'] is None:
                tx['revision'] = rev
                rev += 1
            else:
                tx['revision'] = 0
        out.append(s)
    return {'version': 2, 'sessions': out}

if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    print(json.dumps(build_request(seed), separators=(',', ':')))
